rules = cells('Rules', 'B30:D39')
costs = dict(cells('Leaf costs', 'E30:F32'))

# Build adjacency list: parent -> list of (component, count)
graph = {}
for p, c, n in rules:
    graph.setdefault(p, []).append((c, n))

def get_costs(part):
    if part in costs:
        return {part: costs[part]}
    res = {}
    for comp, mult in graph.get(part, []):
        sub = get_costs(comp)
        for k, v in sub.items():
            res[k] = res.get(k, 0) + v * mult
    return res

def total_cost(part):
    c = get_costs(part)
    return sum(costs[k] * v for k, v in c.items())

result = round(total_cost('Crate') - total_cost('Beacon'), 2)

