from collections import defaultdict
children_map = defaultdict(list)
for parent, comp, units in rules_data:
    children_map[parent].append((comp, int(units)))
leaf_costs = {}
def get_leaf_costs(part):
    if part in leaf_costs:
        return leaf_costs[part]
    if part not in children_map:
        return {}
    totals = defaultdict(float)
    for comp, mult in children_map[part]:
        if comp in cost_map:
            totals[comp] += mult
        else:
            sub = get_leaf_costs(comp)
            for leaf, sub_mult in sub.items():
                totals[leaf] += mult * sub_mult
    leaf_costs[part] = totals
    return totals
